static inline void __switch_to_envcfg(struct task_struct *next)
{
  asm volatile (ALTERNATIVE("nop",
    "csrw " __stringify(CSR_ENVCFG) ", %0", ...)
    :: "r" (next->thread.envcfg) : "memory");
}

